100	async function answerUserMessage(
101	  ws: WebSocket,
102	  session: ChatSession,
103	  orchestrator: ChatOrchestrator,
104	  validation: ValidationResult,
105	  signal: AbortSignal | undefined
106	): Promise<void> {
107	  const message = validation.valid ? validation.data : undefined;
108	  if (message?.type === 'user_message') return handleUserMessage(ws, session, orchestrator, message.content, signal);
109	  answerFrame(ws, validation);
110	}
