112	async function answerFrame(
113	  ws: WebSocket,
114	  validation: ValidationResult,
115	  options?: MessageHandlerOptions
116	): Promise<void> {
117	  if (!validation.valid) {
118	    log.warn('message', 'validation failed', {error: validation.error});
119	    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
120	    return;
121	  }
122	
123	  const message = validation.data;
124	  if (message.type === 'ping') handlePing(ws, message.timestamp);
125	  if (message.type === 'list_conversations') await handleListConversations(ws, message, options);
126	}
