148	async function handleUserMessage(
149	  ws: WebSocket,
150	  session: ChatSession,
151	  orchestrator: ChatOrchestrator,
152	  content: string,
153	  signal: AbortSignal | undefined
154	): Promise<void> {
155	  log.info('message', 'user message received', {sessionId: session.sessionId, contentLength: content.length});
156	
157	  const userEntry = createUserEntry(content);
158	  const userIndex = appendEntry(session, userEntry);
159	  sendUpsert(ws, userIndex, userEntry);
160	
161	  const parser = new ThinkingTagParser();
162	  const state: StreamState = {
163	    thinkingIndex: null,
164	    assistantIndex: null,
165	    suppressOutput: false,
166	    sentAssistantIndices: [],
167	  };
168	
169	  let textChunkCount = 0;
170	
171	  try {
172	    for await (const chunk of orchestrator.processMessageStream(session, {signal})) {
173	      // Its socket closed: breaking returns the run's generator, so the run stops and its own teardown still runs.
174	      if (signal?.aborted) break;
175	      textChunkCount = logChunk(chunk, textChunkCount);
176	      processChunk(ws, session, state, parser, chunk);
177	    }
178	  } finally {
179	    // Anything still open here was cut short: a stop has already flushed the parser and committed every entry it opened.
180	    flushHeldText(ws, session, state, parser);
181	    closeCutOff(ws, session, state, 'thinkingIndex');
182	    closeCutOff(ws, session, state, 'assistantIndex');
183	  }
184	
185	  if (textChunkCount > 0) {
186	    log.debug('stream', `received ${textChunkCount} text chunks`);
187	  }
188	  log.info('stream', 'stream completed', {suppressed: state.suppressOutput, entries: session.entries.length});
189	}
190	
191	// Diagnostics only: counts a run of text chunks so it is logged once, not per token.
192	function logChunk(chunk: MessageChunk, textChunkCount: number): number {
193	  if (chunk.type === 'text') return textChunkCount + 1;
194	
195	  if (textChunkCount > 0) {
196	    log.debug('stream', `received ${textChunkCount} text chunks`);
197	  }
198	
199	  if (chunk.type === 'tool_result') {
200	    log.debug('stream', 'tool_result chunk', {
201	      messageCount: chunk.clientMessages.length,
202	      types: chunk.clientMessages.map(m => m.type),
203	    });
204	    return 0;
205	  }
206	
207	  log.debug('stream', 'chunk', {type: chunk.type});
208	  return 0;
209	}
210	
211	function processChunk(
212	  ws: WebSocket,
213	  session: ChatSession,
214	  state: StreamState,
215	  parser: ThinkingTagParser,
216	  chunk: MessageChunk
217	): void {
218	  if (chunk.type === 'text') return processTextChunk(ws, session, state, parser, chunk.text);
219	  if (chunk.type === 'tool_use') return processToolUseChunk(ws, session, chunk.toolCall);
220	  if (chunk.type === 'tool_result') return processToolResultChunk(ws, chunk.clientMessages);
221	  if (chunk.type === 'suppress_output') return processSuppressChunk(ws, session, state);
222	  if (chunk.type === 'stop') return processStopChunk(ws, session, state, parser);
223	}
224	
225	function processTextChunk(
226	  ws: WebSocket,
227	  session: ChatSession,
228	  state: StreamState,
229	  parser: ThinkingTagParser,
230	  text: string
231	): void {
232	  const segments = parser.push(text);
233	  for (const segment of segments) {
234	    handleTextSegment(ws, session, state, segment);
235	  }
236	}
237	
238	function handleTextSegment(ws: WebSocket, session: ChatSession, state: StreamState, segment: ParsedSegment): void {
239	  if (segment.type === 'thinking') {
240	    streamSegment(ws, session, state, 'thinkingIndex', createThinkingEntry, segment.content);
241	    return;
242	  }
243	  commitAndClear(ws, session, state, 'thinkingIndex');
244	  streamSegment(ws, session, state, 'assistantIndex', createAssistantEntry, segment.content);
245	}
246	
247	function streamSegment(
248	  ws: WebSocket,
249	  session: ChatSession,
250	  state: StreamState,
251	  key: StateIndexKey,
252	  createEntry: EntryFactory,
253	  content: string
254	): void {
255	  const isNew = initSegment(session, state, key, createEntry);
256	  if (isNew && state.suppressOutput) skipSuppressed(ws, session, state[key]!);
257	  if (isNew && !state.suppressOutput) sendUpsert(ws, state[key]!, session.entries[state[key]!]);
258	  appendDelta(session, state[key]!, content);
259	  if (!state.suppressOutput) sendDelta(ws, state[key]!, content);
260	}
261	
262	// Stored as suppressed, so a replay on resume shows the client what it saw live and not the text a tool hid.
263	function skipSuppressed(ws: WebSocket, session: ChatSession, index: number): void {
264	  markSuppressed(session, index);
265	  sendSkip(ws, index);
266	}
267	
268	function markSuppressed(session: ChatSession, index: number): void {
269	  const entry = session.entries[index];
270	  if (entry.role === 'assistant' || entry.role === 'thinking') entry.suppressed = true;
271	}
272	
273	function initSegment(session: ChatSession, state: StreamState, key: StateIndexKey, createEntry: EntryFactory): boolean {
274	  if (state[key] !== null) return false;
275	  state[key] = appendEntry(session, createEntry());
276	  return true;
277	}
278	
279	function commitAndClear(ws: WebSocket, session: ChatSession, state: StreamState, key: StateIndexKey): void {
280	  const index = state[key];
281	  if (index === null) return;
282	
283	  commitEntry(session, index);
284	  state[key] = null;
285	
286	  // Only what the client received can be retracted, and only assistant entries.
287	  if (state.suppressOutput) return;
288	
289	  sendCommit(ws, index);
290	  if (key === 'assistantIndex') state.sentAssistantIndices.push(index);
291	}
292	
293	function processToolUseChunk(
294	  ws: WebSocket,
295	  session: ChatSession,
296	  toolCall: {name: string; input: Record<string, unknown>}
297	): void {
298	  const toolEntry = createToolEntry(toolCall.name, toolCall.input);
299	  const toolIndex = appendEntry(session, toolEntry);
300	  sendUpsert(ws, toolIndex, toolEntry);
301	}
302	
303	function processToolResultChunk(ws: WebSocket, clientMessages: OutgoingMessage[]): void {
304	  for (const msg of clientMessages) {
305	    log.debug('stream', 'forwarding client message to frontend', {
306	      type: msg.type,
307	      index: 'index' in msg ? msg.index : undefined,
308	    });
309	    sendJson(ws, msg);
310	  }
311	}
312	
313	// Retracts what the client saw: every assistant entry sent so far is re-sent blank.
314	function processSuppressChunk(ws: WebSocket, session: ChatSession, state: StreamState): void {
315	  // Closed as streamed so far: an open answer is then retracted like a sent one, and what follows opens new entries.
316	  commitOpenEntries(ws, session, state);
317	  log.debug('stream', 'suppression activated', {blankingEntries: state.sentAssistantIndices});
318	
319	  for (const idx of state.sentAssistantIndices) {
320	    sendUpsert(ws, idx, {...session.entries[idx], content: ''} as SessionEntry);
321	    markSuppressed(session, idx);
322	  }
323	
324	  state.sentAssistantIndices = [];
325	  state.suppressOutput = true;
326	}
327	
328	function processStopChunk(ws: WebSocket, session: ChatSession, state: StreamState, parser: ThinkingTagParser): void {
329	  flushHeldText(ws, session, state, parser);
330	  commitOpenEntries(ws, session, state);
331	}
332	
333	// The parser holds back a tail that might open a tag; without this the tail of a cut-off answer would be lost.
334	function flushHeldText(ws: WebSocket, session: ChatSession, state: StreamState, parser: ThinkingTagParser): void {
335	  for (const segment of parser.flush()) {
336	    handleTextSegment(ws, session, state, segment);
337	  }
338	}
339	
340	// The flag lives on the stored entry even when suppressed; only a visible entry is re-sent, which is how a live client learns it.
341	function closeCutOff(ws: WebSocket, session: ChatSession, state: StreamState, key: StateIndexKey): void {
342	  const index = state[key];
343	  if (index === null) return;
344	  markTruncated(session, index);
345	  if (!state.suppressOutput) sendUpsert(ws, index, session.entries[index]);
346	  commitAndClear(ws, session, state, key);
347	}
348	
349	function commitOpenEntries(ws: WebSocket, session: ChatSession, state: StreamState): void {
350	  commitAndClear(ws, session, state, 'thinkingIndex');
351	  commitAndClear(ws, session, state, 'assistantIndex');
352	}
353	
354	function handlePing(ws: WebSocket, timestamp: number): void {
355	  ws.send(JSON.stringify({type: 'pong', timestamp}));
356	}
357	
358	async function handleListConversations(
359	  ws: WebSocket,
360	  message: ListConversationsMessage,
361	  options?: MessageHandlerOptions
362	): Promise<void> {
363	  if (!options?.history?.enabled || !options.sessionStore?.listFor) {
364	    sendError(ws, ErrorCodes.UNSUPPORTED, 'Conversation history is not enabled');
365	    return;
366	  }
367	  const userId = (ws as ExtWebSocket).userId;
368	  try {
369	    const summaries = await options.sessionStore.listFor(userId, {
370	      limit: message.limit,
371	      before: message.before,
372	    });
373	    sendConversationList(ws, summaries.map(toConversationSummary));
374	  } catch (error) {
375	    const msg = error instanceof Error ? error.message : String(error);
376	    log.error('message', 'list_conversations failed', {error: msg});
377	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list conversations');
378	  }
379	}
380	
381	function toConversationSummary(summary: SessionSummary): ConversationSummary {
382	  return {
383	    sessionId: summary.sessionId,
384	    createdAt:
385	      summary.createdAt instanceof Date ? summary.createdAt.toISOString() : new Date(summary.createdAt).toISOString(),
386	    updatedAt:
387	      summary.updatedAt instanceof Date ? summary.updatedAt.toISOString() : new Date(summary.updatedAt).toISOString(),
388	    entryCount: summary.entryCount,
389	  };
390	}
