22	    jest.setSystemTime(START);
23	  });
24	
25	  afterEach(() => jest.useRealTimers());
26	
27	  it('answers newest activity first, headed by the very session latestFor returns', () => {
28	    const store = new InMemorySessionStore();
29	    store.create('older', 'u1');
30	    jest.setSystemTime(later(1000));
