38	      heads: listed[0]?.sessionId === store.latestFor('u1')?.sessionId,
39	    }).toEqual({order: ['newer', 'older'], heads: true});
40	  });
41	
42	  it('breaks a tie on activity by session id, where latestFor takes the session created later', () => {
43	    const store = new InMemorySessionStore();
44	    store.create('zeta', 'u1');
45	    store.create('alpha', 'u1');
46	
47	    expect({listed: store.listFor('u1').map(row => row.sessionId), latest: store.latestFor('u1')?.sessionId}).toEqual({
48	      listed: ['zeta', 'alpha'],
49	      latest: 'alpha',
50	    });
51	  });
52	
53	  it('reports a creation time, the newest activity and the entry count of each conversation', () => {
54	    const store = new InMemorySessionStore();
55	    const session = store.create('s1', 'u1');
56	    jest.setSystemTime(later(9000));
57	    session.entries.push(
58	      {role: 'user', content: 'hello', timestamp: later(4000).toISOString()},
