    const store = new InMemorySessionStore();
    store.create('a', 'u1');
    store.create('b', 'u1');
    store.create('c', 'u1');

    const pages: string[][] = [];
    let page = store.listFor('u1', {limit: 1});
    while (page.length > 0) {
      pages.push(page.map(row => row.sessionId));
      page = store.listFor('u1', {limit: 1, before: page[0]});
    }

    expect(pages).toEqual([['c'], ['b'], ['a']]);
  });
});

